import { forwardRef } from 'react';

export type StepState = 'completed' | 'active' | 'upcoming';

export type StepProps = {
  state?: StepState;
  title: string;
  description?: string;
};

export type StepperProps = {
  orientation?: 'horizontal' | 'vertical';
  steps: StepProps[];
  className?: string;
};

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

function CheckIcon() {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="3"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

export const Stepper = forwardRef<HTMLDivElement, StepperProps>(
  ({ orientation = 'horizontal', steps, className }, ref) => {
    return (
      <div
        ref={ref}
        className={cn('stepper', `stepper--${orientation}`, className)}
        role="list"
        aria-label="Progress steps"
      >
        {steps.map((step, index) => {
          const state = step.state ?? 'upcoming';
          const isLast = index === steps.length - 1;

          return (
            <>
              <div
                key={`step-${index}`}
                className={cn('stepper__step', `stepper__step--${state}`)}
                role="listitem"
                aria-current={state === 'active' ? 'step' : undefined}
              >
                <div className="stepper__indicator" aria-hidden="true">
                  {state === 'completed' ? <CheckIcon /> : index + 1}
                </div>
                <div className="stepper__content">
                  <span className="stepper__title">{step.title}</span>
                  {step.description && (
                    <span className="stepper__description">{step.description}</span>
                  )}
                </div>
              </div>
              {!isLast && (
                <div
                  key={`conn-${index}`}
                  className={cn(
                    'stepper__connector',
                    state === 'completed' && 'stepper__connector--completed',
                  )}
                  aria-hidden="true"
                />
              )}
            </>
          );
        })}
      </div>
    );
  },
);

Stepper.displayName = 'Stepper';

/* ============================================================
   Stepper — numbered steps with states (completed, active, upcoming)
   Connector is a separate flex item between steps, not absolute.
   ============================================================ */

.stepper {
  display: flex;
  align-items: flex-start;
}

.stepper--horizontal {
  flex-direction: row;
}

.stepper--vertical {
  flex-direction: column;
}

/* ---- Step item ---- */
.stepper__step {
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-3);
  flex-shrink: 0;
}

/* ---- Step indicator (number or checkmark) ---- */
.stepper__indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  border-radius: var(--radius-full);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  line-height: 1;
  transition:
    background-color var(--duration-200) var(--easing-in-out),
    color var(--duration-200) var(--easing-in-out);
}

.stepper__step--upcoming .stepper__indicator {
  background-color: var(--muted);
  color: var(--muted-foreground);
}

.stepper__step--active .stepper__indicator {
  background-color: var(--primary);
  color: var(--primary-foreground);
}

.stepper__step--completed .stepper__indicator {
  background-color: var(--primary);
  color: var(--primary-foreground);
}

/* ---- Step content ---- */
.stepper__content {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-1);
  padding-top: var(--spacing-1);
  min-width: 0;
}

.stepper__title {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  line-height: 1.3;
  color: var(--foreground);
}

.stepper__step--upcoming .stepper__title {
  color: var(--muted-foreground);
}

.stepper__description {
  font-size: var(--font-size-xs);
  line-height: 1.4;
  color: var(--muted-foreground);
}

/* ---- Connector (flex item between steps) ---- */
.stepper__connector {
  background-color: var(--border);
  flex-shrink: 0;
  transition: background-color var(--duration-200) var(--easing-in-out);
}

.stepper__connector--completed {
  background-color: var(--primary);
}

/* Horizontal: line between steps, vertically centered on indicator */
.stepper--horizontal .stepper__connector {
  align-self: flex-start;
  margin-top: 1rem; /* center with 2rem indicator */
  height: var(--stroke-hairline);
  width: var(--spacing-8);
  transform: translateY(-0.5px);
}

/* Vertical: line between steps, horizontally centered on indicator */
.stepper--vertical .stepper__connector {
  margin-left: 1rem; /* center with 2rem indicator */
  width: var(--stroke-hairline);
  height: var(--spacing-6);
  transform: translateX(-0.5px);
}

/* ---- Reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  .stepper__indicator,
  .stepper__connector {
    transition-duration: 0ms;
  }
}
